#!/usr/bin/env bash
# PreToolUse hook (Write|Edit): block edits to generated/build/vendor paths.
# These directories are regenerated by a build tool -- real source lives
# elsewhere, so an edit here is always a mistake, not an intentional change.
set -euo pipefail

input="$(cat)"
file_path="$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty')"
[ -z "$file_path" ] && exit 0

deny() {
  local reason="$1"
  jq -n --arg reason "$reason" \
    '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $reason}}'
  exit 0
}

case "$file_path" in
  */backend/target/*|backend/target/*)
    deny "backend/target is generated by Maven on every build. Edit the real source under backend/src/main/java/... instead." ;;
  */frontend/node_modules/*|frontend/node_modules/*)
    deny "frontend/node_modules is installed by npm, not source. Edit frontend/package.json if you need a dependency change, then run npm install." ;;
  */frontend/dist/*|frontend/dist/*)
    deny "frontend/dist is a Vite build output, regenerated by npm run build. Edit frontend/src/... instead." ;;
  */__pycache__/*|__pycache__/*)
    deny "__pycache__ holds compiled Python bytecode, not source. Edit the matching .py file instead." ;;
  *.pyc)
    deny "This is compiled Python bytecode, not source. Edit the matching .py file instead." ;;
  */.venv/*|.venv/*)
    deny ".venv is a throwaway virtualenv (gitignored, rebuilt from requirements.txt). Don't edit installed packages directly." ;;
  */.pytest_cache/*|.pytest_cache/*)
    deny ".pytest_cache is pytest's run cache, not source -- there's nothing to edit here." ;;
  */postgres_data/*|postgres_data/*)
    deny "postgres_data is the Docker-mounted database volume, not source." ;;
  */chroma_data/*|chroma_data/*)
    deny "chroma_data is the Docker-mounted vector-store volume, not source." ;;
esac

exit 0
